   'form', 'national', '2026-10-13'::date, 'active',
   'Page last updated 30 Oct 2023. AA9/12 for professional activity; business/craft activity uses Comunicazione Unica instead. Nomad only.', array['partita-iva']::text[]),
  ('us-los-angeles-consular-tariff-q4-2026', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'Estratto tabella diritti consolari – 1 Oct to 31 Dec 2026', 'Consulate General of Italy Los Angeles',
   'https://conslosangeles.esteri.it/it/servizi-consolari-e-visti/servizi-per-il-cittadino-italiano/altri-servizi/albo-consolare/estratto-tabella-diritti-consolari/',
   'consular_guidance', 'national', '2026-10-13'::date, 'active',
   'Q4 2026 extract of the consular tariff table (D.Lgs. 71/2011) hosted by a US post; rate EUR 1 = USD 1.1516; type D visa EUR 116 / USD 133.60. Same figures in Chicago and Miami Q4 2026 PDFs. Quarterly: re-verify after 31 Dec 2026.', array['visa-fee']::text[]),
  ('us-washington-visa-fees', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'Visa fees (1 Oct to 31 Dec 2026)', 'Embassy of Italy Washington',
