   'Last update 2 Oct 2026. National visa USD 133.60 for Q4 2026; payment at the appointment by cashier''s check/money order or exact cash. Quarterly.', array['visa-fee']::text[]),
  ('us-new-york-visa-general', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'General information – visas (New York)', 'Consulate General of Italy New York',
