  ('it-gu-dm-2024-02-29-art2', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'Interministerial decree 29 February 2024 (Art. 2 – Definizioni)', 'Gazzetta Ufficiale',
   'https://www.gazzettaufficiale.it/atto/serie_generale/caricaArticolo?art.versione=1&art.idGruppo=0&art.flagTipoArticolo=0&art.codiceRedazionale=24A01716&art.idArticolo=2&art.idSottoArticolo=1&art.idSottoArticolo1=10&art.dataPubblicazioneGazzetta=2024-04-04&art.progressivo=0',
