  ('it-gu-dm-2024-02-29-art3', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'Interministerial decree 29 February 2024 (Art. 3 – Requisiti)', 'Gazzetta Ufficiale',
   'https://www.gazzettaufficiale.it/atto/serie_generale/caricaArticolo?art.versione=1&art.idGruppo=0&art.flagTipoArticolo=0&art.codiceRedazionale=24A01716&art.idArticolo=3&art.idSottoArticolo=1&art.idSottoArticolo1=10&art.dataPubblicazioneGazzetta=2024-04-04&art.progressivo=0',
   'decree', 'national', '2026-10-13'::date, 'active',
   'Art. 3.1(a)-(d): income vs ticket-exemption minimum, health insurance, accommodation documentation, 6 months'' prior experience; 3.1(e) refers to art. 27-quater. Remote-only items in separate row. Art. 3.1(e): contract or binding offer for remote workers; Art. 3.4-3.5: employer declaration of no convictions (art. 22 c.5-bis TU).', array['proof-of-income', 'health-insurance', 'accommodation', 'prior-experience', 'highly-qualified', 'employment-contract']::text[]),
  ('it-gu-dm-2024-02-29-art4', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'Interministerial decree 29 February 2024 (Art. 4 – Permesso di soggiorno)', 'Gazzetta Ufficiale',
   'https://www.gazzettaufficiale.it/atto/serie_generale/caricaArticolo?art.versione=1&art.idGruppo=0&art.flagTipoArticolo=0&art.codiceRedazionale=24A01716&art.idArticolo=4&art.idSottoArticolo=1&art.idSottoArticolo1=10&art.dataPubblicazioneGazzetta=2024-04-04&art.progressivo=0',
   'decree', 'questura', '2026-10-13'::date, 'active',
   'Apply at the Questura within 8 working days of entry; permesso ''nomade digitale - lavoratore da remoto'' up to 1 year, renewable; show visa documentation stamped by the consulate; family reunification.', array['permesso-soggiorno']::text[]),
  ('it-gu-dm-2024-02-29-art6', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'Interministerial decree 29 February 2024 (Art. 6 – Codice fiscale and partita IVA)', 'Gazzetta Ufficiale',
   'https://www.gazzettaufficiale.it/atto/serie_generale/caricaArticolo?art.versione=1&art.idGruppo=0&art.flagTipoArticolo=0&art.codiceRedazionale=24A01716&art.idArticolo=6&art.idSottoArticolo=1&art.idSottoArticolo1=10&art.dataPubblicazioneGazzetta=2024-04-04&art.progressivo=0',
   'decree', 'questura', '2026-10-13'::date, 'active',
   'Art. 6.1: codice fiscale generated and communicated by the Questura when the permesso is issued. Art. 6.2: digital nomads also request a partita IVA under art. 35 DPR 633/1972.', array['codice-fiscale', 'partita-iva']::text[]),
  ('it-normattiva-dlgs-286-1998-art4', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'Consolidated immigration act D.Lgs. 286/1998 – art. 4 (Ingresso)', 'Normattiva',
